const canvas=document.getElementById('floorCanvas'),empty=document.getElementById('emptyState');
const $=id=>document.getElementById(id);let items=[],selected=null,history=[],future=[],drag=null;const PX=40;
const colors={リビング:'#f1e7d4',寝室:'#eee1dc',キッチン:'#e2ebdf',水まわり:'#dce9ee'};
function uid(){return 'i'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function snap(n){return $('snapToggle').checked?Math.round(n/20)*20:n}
function state(){return JSON.stringify(items)}
function checkpoint(){history.push(state());if(history.length>40)history.shift();future=[]}
function addItem(type,name,w,h,x,y,skip=false){if(!skip)checkpoint();const count=items.filter(i=>i.name.startsWith(name)).length+1;let item={id:uid(),type,name:type==='room'?`${name} ${count}`:name,x:x??80+items.length*18,y:y??80+items.length*16,w:w||(type==='furniture'?110:80),h:h||(type==='furniture'?55:type==='door'?55:18),rotation:0,color:colors[name]||'#e7e5dd'};items.push(item);render();select(item.id);scheduleSave()}
function render(){canvas.querySelectorAll('.plan-item').forEach(e=>e.remove());items.forEach(item=>{const el=document.createElement('div');el.className=`plan-item ${item.type}${item.id===selected?' selected':''}`;el.dataset.id=item.id;Object.assign(el.style,{left:item.x+'px',top:item.y+'px',width:item.w+'px',height:item.h+'px',background:item.type==='door'?'transparent':item.color,transform:`rotate(${item.rotation}deg)`});const area=(item.w/PX)*(item.h/PX);el.innerHTML=`<div class="item-label"><strong>${item.name}</strong>${item.type==='room'?`<small>${area.toFixed(1)} m²</small>`:''}</div><span class="resize-handle"></span>`;el.addEventListener('pointerdown',startDrag);canvas.appendChild(el)});empty.style.display=items.length?'none':'flex';updateSummary();updateInspector()}
function startDrag(e){e.preventDefault();const id=e.currentTarget.dataset.id;select(id);const item=items.find(i=>i.id===id);checkpoint();drag={id,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y,w:item.w,h:item.h,resize:e.target.classList.contains('resize-handle')};window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',endDrag,{once:true})}
function onMove(e){if(!drag)return;const item=items.find(i=>i.id===drag.id),z=Number($('zoom').value)/100,dx=(e.clientX-drag.startX)/z,dy=(e.clientY-drag.startY)/z;if(drag.resize){item.w=Math.max(30,snap(drag.w+dx));item.h=Math.max(20,snap(drag.h+dy))}else{item.x=Math.max(0,Math.min(canvas.clientWidth-item.w,snap(drag.x+dx)));item.y=Math.max(0,Math.min(canvas.clientHeight-item.h,snap(drag.y+dy)))}render()}
function endDrag(){window.removeEventListener('pointermove',onMove);drag=null;scheduleSave()}
function select(id){selected=id;render()}
function updateInspector(){const item=items.find(i=>i.id===selected);$('noSelection').classList.toggle('hidden',!!item);$('propertyForm').classList.toggle('hidden',!item);if(!item)return;$('propName').value=item.name;$('propW').value=(item.w/PX).toFixed(1);$('propH').value=(item.h/PX).toFixed(1);$('propRotation').value=item.rotation;$('rotationLabel').textContent=item.rotation+'°';document.querySelectorAll('#swatches button').forEach(b=>b.classList.toggle('active',b.dataset.color===item.color))}
function updateSummary(){const rooms=items.filter(i=>i.type==='room'),area=rooms.reduce((a,i)=>a+(i.w/PX)*(i.h/PX),0);$('roomCount').textContent=rooms.length;$('totalArea').textContent=area.toFixed(1)+' m²';$('statusSummary').textContent=`${rooms.length} 部屋 ・ ${area.toFixed(1)} m²`}
function mutate(fn){const item=items.find(i=>i.id===selected);if(!item)return;checkpoint();fn(item);render();scheduleSave()}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addItem(b.dataset.add,b.dataset.name,+b.dataset.w||0,+b.dataset.h||0));
$('propName').onchange=e=>mutate(i=>i.name=e.target.value||'名称未設定');$('propW').onchange=e=>mutate(i=>i.w=Math.max(20,+e.target.value*PX));$('propH').onchange=e=>mutate(i=>i.h=Math.max(20,+e.target.value*PX));$('propRotation').oninput=e=>mutate(i=>i.rotation=+e.target.value);document.querySelectorAll('#swatches button').forEach(b=>b.onclick=()=>mutate(i=>i.color=b.dataset.color));
$('deleteBtn').onclick=()=>{if(!selected)return;checkpoint();items=items.filter(i=>i.id!==selected);selected=null;render();scheduleSave()};$('duplicateBtn').onclick=()=>{const i=items.find(x=>x.id===selected);if(i)addItem(i.type,i.name.replace(/ \d+$/,''),i.w,i.h,i.x+20,i.y+20)};
$('undoBtn').onclick=()=>{if(!history.length)return;future.push(state());items=JSON.parse(history.pop());selected=null;render();scheduleSave()};$('redoBtn').onclick=()=>{if(!future.length)return;history.push(state());items=JSON.parse(future.pop());selected=null;render();scheduleSave()};
$('zoom').oninput=e=>{canvas.style.transform=`scale(${e.target.value/100})`;$('zoomLabel').textContent=e.target.value+'%'};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
let saveTimer;function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,500)}function save(){localStorage.setItem('madori-data',JSON.stringify({items,name:$('projectName').value}));toast('保存しました')}$('saveBtn').onclick=save;$('projectName').onchange=scheduleSave;
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}
$('exportBtn').onclick=()=>{const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="620"><rect width="100%" height="100%" fill="#fdfcf9"/>${items.map(i=>`<g transform="translate(${i.x} ${i.y}) rotate(${i.rotation} ${i.w/2} ${i.h/2})"><rect width="${i.w}" height="${i.h}" fill="${i.type==='door'?'none':i.color}" stroke="#56615b" stroke-width="2"/><text x="${i.w/2}" y="${i.h/2}" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif" font-size="13" fill="#25312d">${i.name.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}</text></g>`).join('')}</svg>`;const image=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));image.onload=()=>{const c=document.createElement('canvas');c.width=900;c.height=620;c.getContext('2d').drawImage(image,0,0);const a=document.createElement('a');a.download=($('projectName').value||'間取り')+'.png';a.href=c.toDataURL('image/png');a.click();URL.revokeObjectURL(url);toast('PNGを書き出しました')};image.src=url};
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='z'){$('undoBtn').click();e.preventDefault()}if((e.key==='Delete'||e.key==='Backspace')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))$('deleteBtn').click()});canvas.onclick=e=>{if(e.target===canvas){selected=null;render()}};
try{const d=JSON.parse(localStorage.getItem('madori-data'));if(d){items=d.items||[];$('projectName').value=d.name||'わが家のプラン A'}}catch{}render();
